// Generated by scripts/sync-help.mjs from pzza-code-web/components/docs/agents/DictationShot.tsx. Regenerate with `npm run sync:help` rather than editing.
/**
 * Dictation: a session tile whose microphone is recording, ported from the
 * app's tile header (SessionHeader and the header buttons in
 * src/grid/Canvas.tsx, Worktrees.tsx, Checkpoints.tsx) and its
 * DictationButton (src/ui/Dictation.tsx), styled by the app's stylesheet.
 * While the scene is on screen the button plays one dictation: Start
 * dictation, the level meter while you speak, the finishing wave while the
 * last phrase is written, and back. A click on the button starts or stops
 * it by hand; any click or keystroke in the scene ends the loop.
 */
import { useEffect, useRef, useState, type ReactNode } from "react";
import { Copy, EyeOff, FileCode, FolderGit2, FolderInput, History, Maximize2, Mic, Square, X } from "lucide-react";
import { AgentMark, Brand, Term, TileStrip, TopBar, Window } from "../../home/AppUI";
import { AnsiScreen } from "../../home/ansi";
import { Shot } from "../../home/Chrome";
import { windowPanels } from "../../home/Dropdowns";
import { ActiveCanvas, ToolsBar, WorkspaceTabs } from "../../home/Interactive";
import { usePanelLoop } from "../../home/panel-loops";
import { SESSIONS, SessionTile, WIN_SIZE } from "../../home/Scenes";
import { MacIcon } from "./parts";

type Phase = "idle" | "listening" | "finalizing";

// DictationButton's bars and how each answers the input level.
const WAVE_HEIGHTS = [0.4, 0.75, 1, 0.75, 0.4];
const LEVEL_MS = 90;

/* The loop: the tile at rest, a few seconds of speech (the level rises and
   falls with the words, with short pauses), the final pass, and rest again. */
const REST_MS = 2200;
const SPEAK_MS = 3600;
const FINISH_MS = 1300;

/** A speaking voice's level at `t` ms: syllables over words, with gaps between phrases. */
function speechLevel(t: number): number {
  const phrase = (t % 1800) / 1800;
  if (phrase > 0.82) return 0.04;
  const syllables = 0.55 + 0.45 * Math.abs(Math.sin(t / 95));
  const words = 0.6 + 0.4 * Math.sin(t / 410);
  return Math.min(1, syllables * words);
}

/** The app's DictationButton for this tile's recording. */
function DictationButton({ phase, level, voice, onClick }: { phase: Phase; level: number; voice: boolean; onClick: () => void }) {
  const active = phase !== "idle";
  const finishing = phase === "finalizing";
  const title = finishing ? "Finishing dictation. Click to cancel." : active ? "Stop dictation" : "Start dictation";
  const status = finishing ? "Finishing dictation" : voice ? "Hearing speech" : "Listening";
  const shown = phase === "listening" ? level : 0;
  return (
    <button
      type="button"
      className={`tile-btn ${active ? "dictation-mic-on" : ""}`}
      title={title}
      aria-label={active ? `${title} (${status})` : title}
      aria-busy={finishing}
      onClick={onClick}
    >
      {active ? (
        <>
          <span className={`dictation-wave${finishing ? " dictation-wave-finishing" : ""}`} aria-hidden="true">
            {WAVE_HEIGHTS.map((height, index) => (
              <span key={index} style={{ transform: `scaleY(${0.15 + shown * height * 0.85})` }} />
            ))}
          </span>
          <Square size={12} />
        </>
      ) : (
        <Mic size={13} />
      )}
    </button>
  );
}

/** A plain header button (Canvas.tsx's tile-btn buttons). */
function HeadButton({ title, label, children, danger }: { title: string; label?: string; children: ReactNode; danger?: boolean }) {
  return (
    <button type="button" className={`tile-btn ${danger ? "tile-btn-danger" : ""}`} title={title} aria-label={label ?? title}>
      {children}
    </button>
  );
}

function DictationTile() {
  const [phase, setPhase] = useState<Phase>("idle");
  const [level, setLevel] = useState(0);
  const root = useRef<HTMLDivElement>(null);
  const started = useRef(0);

  // The level meter follows the voice while listening.
  useEffect(() => {
    if (phase !== "listening") return;
    started.current = performance.now();
    const timer = window.setInterval(() => setLevel(speechLevel(performance.now() - started.current)), LEVEL_MS);
    return () => window.clearInterval(timer);
  }, [phase]);

  usePanelLoop(
    root,
    async (wait) => {
      setPhase("idle");
      await wait(REST_MS);
      setPhase("listening");
      await wait(SPEAK_MS);
      setPhase("finalizing");
      await wait(FINISH_MS);
      setPhase("idle");
    },
    () => setPhase("idle"),
  );

  // By hand: start, stop (the final pass), or cancel the final pass.
  const click = () => {
    if (phase === "idle") setPhase("listening");
    else if (phase === "listening") {
      setPhase("finalizing");
      window.setTimeout(() => setPhase((current) => (current === "finalizing" ? "idle" : current)), FINISH_MS);
    } else setPhase("idle");
  };

  // Header actions in the app's order and groups: input | Git | session | view | close.
  const actions: { id: string; group: string; button: ReactNode }[] = [
    { id: "mic", group: "input", button: <DictationButton phase={phase} level={level} voice={level > 0.1} onClick={click} /> },
    { id: "code", group: "input", button: <HeadButton title="Code editor"><FileCode size={13} /></HeadButton> },
    {
      id: "worktrees",
      group: "git",
      button: (
        <HeadButton title={"Worktrees\nThe Git worktrees of this session's repository, or of the repositories in its folder"} label="Worktrees">
          <FolderGit2 size={13} aria-hidden="true" />
        </HeadButton>
      ),
    },
    {
      id: "checkpoints",
      group: "git",
      button: (
        <HeadButton title={"3 checkpoints of this folder\nClick to compare or restore them"} label="Open 3 checkpoints">
          <History size={13} aria-hidden="true" />
        </HeadButton>
      ),
    },
    { id: "move", group: "session", button: <HeadButton title="Move to workspace"><FolderInput size={13} /></HeadButton> },
    { id: "duplicate", group: "session", button: <HeadButton title="Duplicate session"><Copy size={13} /></HeadButton> },
    { id: "fullscreen", group: "view", button: <HeadButton title="Maximize (double-click the header)" label="Maximize"><Maximize2 size={13} /></HeadButton> },
    { id: "hide", group: "view", button: <HeadButton title="Hide (keeps running)"><EyeOff size={13} /></HeadButton> },
    { id: "close", group: "close", button: <HeadButton title="Terminate" danger><X size={14} /></HeadButton> },
  ];

  return (
    <div ref={root} className="tile tile-active">
      <div className="tile-head">
        <span className="stat stat-idle" title="idle" />
        <span className="tile-icon">
          <span title="Launcher: Claude Code. Effective model unavailable." style={{ display: "inline-flex" }}>
            <AgentMark agent="claude" tinted />
          </span>
        </span>
        <span className="tile-title" title={"web\nClick to rename"}>
          web
        </span>
        <kbd className="kbd tile-kbd" title="Activate">
          ⌘3
        </kbd>
        <span className="tile-device" title="Running on This Device">
          <MacIcon size={11} />
          <span className="tile-device-name">This Device</span>
        </span>
        <div className="tile-head-spacer" />
        <div className="tile-actions">
          {actions.map(({ id, group, button }, index) => (
            <span key={id} className={`tile-action tile-action-${id}${index > 0 && actions[index - 1].group !== group ? " tile-action-group-start" : ""}`}>
              {button}
            </span>
          ))}
        </div>
      </div>
      <div className="tile-body">
        <Term>
          <AnsiScreen id="web-57" />
        </Term>
      </div>
      <TileStrip s={{ session: "web", branch: "main", path: SESSIONS.web.path, started: SESSIONS.web.started }} />
    </div>
  );
}

/* The card zooms in on the recording tile: a 3 x 2 grid in the 1440 x 900
   window puts it top right at about 963-1430 x 52-466, and the card shows
   a 480 x 208 region around its header and first terminal lines at 1.5x, so
   the microphone and its level meter are the subject: from the gap before
   the column to the window's edge, and from under the top bar to between
   the eleventh and twelfth terminal rows (the terminal starts at 89, in
   15px rows). The Stage never enlarges a scene past its own size, hence
   the zoom here. */
const REGION = { left: 956, top: 46, width: 480, height: 208 };
const ZOOM = 1.5;

export function DictationShot() {
  return (
    <Shot id="chat" width={REGION.width * ZOOM} height={REGION.height * ZOOM}>
      <div style={{ position: "absolute", left: 0, top: 0, width: REGION.width, height: REGION.height, transform: `scale(${ZOOM})`, transformOrigin: "0 0" }}>
        <Window style={{ left: -REGION.left, top: -REGION.top, ...WIN_SIZE }}>
          <TopBar>
            <Brand />
            <WorkspaceTabs />
            <ToolsBar panels={windowPanels({ height: WIN_SIZE.height })} />
          </TopBar>
          <ActiveCanvas
            initial={2}
            style={{ gridTemplateColumns: "1fr 1fr 1fr", gridTemplateRows: "1fr 1fr" }}
            tiles={[
              <SessionTile key="api" id="api" capture="api-57" kbd="⌘1" />,
              <SessionTile key="docs" id="docs" capture="docs-57" kbd="⌘2" />,
              <DictationTile key="web" />,
              <SessionTile key="release" id="release" capture="release-57" kbd="⌘4" />,
            ]}
          />
        </Window>
      </div>
    </Shot>
  );
}
